import { createClient } from "redis";

const redis = createClient();
await redis.connect();

for (;;) {
  await redis.watch("balance");
  const balance = Number((await redis.get("balance")) ?? 0);
  if (balance < 10) {
    await redis.unwatch();
    break;
  }

  const result = await redis.multi()
    .decrBy("balance", 10)
    .incr("purchases")
    .exec();

  if (result !== null) break;
}

await redis.close();

